using System.Collections.Frozen;
using MegaCrit.Sts2.Core.Entities.Powers;

namespace CombatSolver.HotKernel;

internal readonly record struct HotPowerCatalogEntry(
    HotPowerId Id,
    string Entry,
    HotPowerDomain Domain,
    PowerType Type,
    PowerStackType StackType,
    HotHookMask HookMask,
    bool CanHealPlayer,
    bool HasRelevantTurnStartAmount,
    bool HasRelevantSkipDurationTick,
    short SetupWeight,
    PowerInstanceType InstanceType = PowerInstanceType.None);

/// <summary>
/// Static STS2 0.114.0 catalog covering all vanilla concrete powers with exact types, hook masks, and setup weights.
/// </summary>
internal static class HotPowerCatalog
{
    public static readonly HotPowerCatalogEntry[] ById = BuildById();
    public static readonly FrozenDictionary<string, HotPowerId> IdByEntry = BuildIdByEntry();

    public static HotPowerId FindByEntry(string entry)
        => IdByEntry.TryGetValue(entry, out HotPowerId id) ? id : HotPowerId.None;

    public static ref readonly HotPowerCatalogEntry Get(HotPowerId id)
    {
        int idx = (int)id;
        return ref ById[(uint)idx < (uint)ById.Length ? idx : 0];
    }

    public static HotHookMask GetHookMask(string entry)
        => Get(FindByEntry(entry)).HookMask;

    private static FrozenDictionary<string, HotPowerId> BuildIdByEntry()
    {
        Dictionary<string, HotPowerId> map = new(ById.Length, StringComparer.Ordinal);
        for (int i = 1; i < ById.Length; i++)
            map[ById[i].Entry] = ById[i].Id;
        return map.ToFrozenDictionary(StringComparer.Ordinal);
    }

